    {"^Your next ([%d%.,%-]+) instances of Holy damage are increased by ([%d%.,%-]+)%%%.  Lasts (%d[%d%.,]*%s%a+)%.$", "Dine næste {1} Helligskader øges med {2}%.  Varer {3}.", " instances of Holy damage are increased by ", "Y"},
    {"^(.-) is already in an arena team of that size%.$", "{1} er allerede i et arenahold af den størrelse.", " is already in an arena team of that size.", ""},
    {"^([%d%.,%-]+) Shadow damage inflicted every ([%d%.,%-]+) sec%.\nHealth regeneration rate reduced by ([%d%.,%-]+)%%%.$", "{1} Skyggeskade forvoldt hvert {2}. sek.\nLivsgenopretningshastighed reduceret med {3}%.", " sec.\nHealth regeneration rate reduced by ", ""},
    {"^([%d%.,%-]+) Shadow damage inflicted every second for (%d[%d%.,]*%s%a+)%.\nMovement speed reduced to ([%d%.,%-]+)%% of normal%.$", "{1} Skyggeskade forvoldt hvert sekund i {2}.\nBevægelseshastighed reduceret til {3}% af normal.", " Shadow damage inflicted every second for ", ""},
